## Code Example

```typescript
// TypeScript interface for cross-platform API
interface NotificationScheduler {
  scheduleNotification(params: {
    id: string;
    title: string;
    body: string;
    timestamp: number;
    repeat?: 'daily' | 'weekly' | 'monthly';
  }): Promise<void>;

  cancelNotification(id: string): Promise<void>;

  onNotificationOpen: (callback: (notification: NotificationData) => void) => void;
}

// Usage example
const scheduler = new NotificationScheduler();

// Schedule notification
await scheduler.scheduleNotification({
  id: 'meeting-reminder',
  title: 'Team Meeting',
  body: 'Daily standup in 15 minutes',
  timestamp: Date.now() + 15 * 60 * 1000, // 15 minutes from now
  repeat: 'daily'
});

// Listen for notification opens
scheduler.onNotificationOpen((notification) => {
  console.log('Notification opened:', notification);
  // Navigate to relevant screen
});
```

